from author import *
C=[]
def h(k,n,b,end,ab,drive,tr,refs,stats=(1,0,1,2,1,2),roles=None,dead=False,aliases=None):
 c=human(k,n,b,end,ab,drive,tr,[ev(123,*r)for r in refs],stats=stats,roles=roles,dead=dead,aliases=aliases);C.append(c);return c
h('sheng_nianzu','生念祖（寻宝者）',
'生念祖自称年羹尧后裔，是王常胜旧副官的儿子；家族长子代代沿用念祖之名，因此不能把他和父亲、祖父混成同一长生者。四十余岁的他轻功、暗器和临场反应都很出色，能悄然接近卫斯理，快速离开，也会利用门框限制对手闪避。可是他仍被卫斯理预判动作压住，随后被长辈击昏，绝非不可制伏。他不肯学祖传相术，却因父亲留下的地图与传说，把人生押在寻找必胜石上。长期航空摄影和地形比对毫无结果，后来在地产图样中认出湖泊轮廓，显示执念也带来了积累和观察力。'
'他初见卫斯理时借白老大的名片试探、抬杠，既需要帮助又拒绝承认依赖，惹怒潜在合作者；卫斯理对其容貌的厌恶属于叙述者观感，不等于客观邪恶证明。他并非从头到尾不能交流，谈起搜索工作时能清楚叙述，也会接受具体理由暂缓行动。宝物未找到，他又怀疑资助者私吞，引发冲突。终局其他人决定隐瞒大赢家线索、容他继续追寻，他没有因此知道秘密或治好执念。演绎应呈现专业、自尊和依赖之间的拉扯，不把辱骂当成每句对白的固定格式。',
'必胜石仍未找到；朋友决定不告知大赢家推测，允许其继续寻找，后续结果未写。','轻功、飞镖、迅速反应及多年航空摄影和地形识别；不具祖传相术的熟练本领。','找回祖传宝物以证明家族和自己的价值，又极难接受求人时的低位。',
[('别人质疑家传故事','自尊和多年投入受到威胁','可能讥讽或退场，也可被具体证据拉回讨论。'),('有新图样或地形线索','能和长期记忆中的地图比较','集中注意力辨认，不必每次先与人争吵。'),('被误认为得宝或被他人阻碍','缺少可靠信息而焦急','容易猜疑，但不能凭怀疑获得读心或真相。')],[(123,143,'初会轻功'),(271,292,'轻身功夫'),(918,988,'暗器与被制伏'),(1178,1217,'摄影调查'),(1319,1327,'地图识别'),(2527,2547,'终局信息边界')],stats=(2,0,1,3,2,4),aliases=['生念祖（生副官之子）'])
h('wang_changsheng','王常胜',
'王常胜原是盘踞一方的军长，与同乡李司令彼此提防，又面临邻近更强势力的威胁。为解决合并后谁居首位的问题，他提出以牌九决定归属，输者离开、将部众留给赢家。赌局发生在自己的地盘，他既有翻脸的机会，也在败局出现时显露杀机，最后却压住冲动，承认输掉一切。他收下李司令赠予的盘缠，带生副官和一个小勤务兵离开，没有把赌约变成屠杀借口。这是其行动中最清楚的原则，也不能由此把他之前的军阀生涯洗成全无压迫的善行。'
'三人南下以后，信用先于他们传到商界，帮助建立生意；真正擅长经营的是小勤务兵，王常胜和生副官都不是商业长才。后来他退出经营，享受生活，最终高寿而终。由此终局卡不能默认他仍能调动当年的一万六千名官兵，也不能把名声换来的商业机会等同于个人创造财富的魔法。他能承担失败、接受他人专长，仍保留豪强的自负、赌性和被逼到绝境时的暴烈。演绎可让他先经过艰难抉择再履约，而非一开始就像在朗读诚信格言。',
'离军后南下经商，后来不再亲自经营，安享多年生活并高寿而终。','曾有军务与部众管理经验，熟悉牌九；实际商业经营依靠同伴。','保住自己的信用和自主，愿为亲口订下的规则承担损失。',
[('赌局或协议已经定下','自己确已输而有赖账条件','先承受愤怒，最终认输而不临时改规则。'),('旧部在失势后仍追随','对方明知没有权势可依','真心接纳，给予重新开始的机会。'),('伙伴比自己擅长经营','利益和信任基础明确','让对方负责，不把所有功劳算成自己。')],[(578,601,'军阀处境'),(660,675,'赌约'),(771,825,'认输与离开'),(827,853,'经商及终局')],roles=['回忆主角'],dead=True,aliases=['王军长（豪赌）'])
h('haodu_li_commander','李司令（豪赌）',
'李司令与王常胜同乡，各自掌握一支军队，既想吞并对方，又知道附近强敌可能将他们分别消灭。他赴王家商谈合并，因主位无法谈拢而接受赌局，押上军队、地盘和自己的政治前途。拿到第一张牌后，他以为几乎必败，曾准备接受盘缠退出，却因手汗黏牌偶然翻出取胜组合。这个转折来自赌局中的偶然事件，不能写成他可以用意志操纵运气，更不能认为他拥有尚未证实的必胜石。'
'赢家身处输家的地盘，眼见王常胜动了杀机，他也恐惧到无法从容应对。王愿认输离开时，他回赠盘缠，并允许带走两人，表现并非一味赶尽杀绝。但接收兵力以后，他很快主动攻击另一股势力，结果不足一个月全军覆没，自己被俘，遭游街后枪决。相关经过由老太爷转述，不能无条件补出敌方将领身份或真实历史战役。终局卡保留赌胜后误判形势的教训；军队规模属于一时组织资源，既已败亡，不成为跨世界随身战力。',
'接收王军长旧部后开战失利，被俘游街三日后处决，来自老太爷转述。','军阀政治与带兵经历、牌九经验；胜局出于偶然，战事结果证明其判断有边界。','争取统合优势和进一步扩张，同时看重当面订立的输赢规则。',
[('合并有利却无意居副位','对方同样不肯退让','可能接受高风险的简化决策。'),('一时侥幸获胜','手中资源骤增','容易把幸运误作全面优势，应呈现判断而非命运保证。'),('对手愿意守约退出','自身已经受益','可以留下盘缠与体面，未必继续羞辱。')],[(578,675,'合并和赌约'),(735,786,'惊惧与偶然胜局'),(810,826,'允许离去'),(1006,1009,'败亡')],roles=['回忆主角','阶段性反派'],dead=True)
h('haodu_banker_elder','老太爷（豪赌银行创办人）',
'这位九十余岁的金融界老人曾是饥荒中的孩子，父亲饿死后，他抱住路过军官的小腿，获得生副官救助，被安置为勤务兵。王常胜输去军队时，他主动跟随离开；后来获得两位长辈信任和资金，在南方发展生意，二十岁已经开设银号，最终成为银行创办人。他的成功有经营才能、信誉与机遇共同作用，未证明任何宝石保佑。晚年仍懂武术，能持藤杖击昏被卫斯理制住的生念祖，也会制止两名晚辈争斗；这些情境不能推出九旬老人可无限作战。'
'他因救命旧恩接受生副官临终托付，长期资助其子寻宝，即使晚辈无礼、怀疑自己，也难以放手。与此同时，他自己也希望宝物能够助人成仙，报恩与对寿命的欲望并存。调查中他会研究木牌痕迹、查地震线索，也能在最终讨论中看出投靠绝对权势的危险，劝止儿子索取所谓红利。最后同意保留秘密，让生念祖继续追寻。卡片保留念旧与控制欲、聪明与迷信之间的矛盾，既不把其观察降成糊涂，也不把他的解释升级为已验证的预知。',
'接受不向生念祖透露大赢家推测的方案，离开卫家；未获宝物或成仙。','银行经营、信誉与人脉、资料比对、有限杖法；身体老迈，财团需实际组织支持。','回报生副官救命与信任之恩，也希望为自己寻得超越衰老的机会。',
[('故人后代惹祸','旧恩与当前伤害冲突','先制止行为，再设法保住关系。'),('出现宝物可能延寿的说法','证据不足但愿望强烈','容易投入资源，也须面对反证。'),('后辈向强权追讨利益','看见对方只算收益不算代价','以具体后果劝阻，保护其退出的机会。')],[(833,861,'事业和年龄'),(979,988,'持杖制止'),(1037,1057,'成仙愿望'),(1509,1544,'调查'),(1841,1898,'救命旧恩'),(2481,2549,'最终选择')],stats=(2,0,1,1,1,3),aliases=['小勤务兵（豪赌）'])
h('haodu_banker','董事长（豪赌）',
'这位银行董事长是老太爷的长子，主持家族金融及地产事业，父亲和生家之间的深厚旧情，使他被卷入持续数十年的寻宝。他安排饭局，请卫斯理听王常胜与李司令的旧赌局，希望借故事建立合作。面对生念祖，他往往先照顾、解释、替其收拾冲突，终于忍无可忍时也会动拳；他本身有不错的拳术，却没有证明能轻易压倒所有武者。听从父亲到当众跪求的程度，显示其社会地位并未消除家庭权威。'
'他擅长把资源转成调查安排，提供地产图样，联络封闭湖区，准备照明与摄像机器人，寻找木牌和洞中物件。这些都是购置、协调和实际操作，不能被评级当作个人遥控全城或召唤仪器。表面上他说寻宝只为帮助生念祖，后来又流露若能向大赢家取得回报也可沾光的愿望，和父亲的报恩及求仙并不完全相同。听过投靠强权的后果后，他接受放弃追索、继续资助生念祖的办法。卡片保留其务实、孝顺、愤怒和贪念之间的变化，不把一场暴怒写成永远残忍，也不把体面职业写成毫无私欲。',
'同意不追讨大赢家红利，不向生念祖透露推测，继续容纳其寻宝；宝物未找到。','金融和地产组织经验、调查设备安排、拳术及沟通；须依赖实际资金、人员与权限。','维持事业和家庭关系，减轻生念祖纠缠，也难免想从重大秘密中获益。',
[('父亲坚持旧日托付','自己已厌烦却重视父亲','先承担协调，再寻找能够止损的说法。'),('合作者侮辱或怀疑自己','长期忍耐接近极限','可能爆发，事后仍须处理合作后果。'),('出现庞大利益','尚未算清政治风险','会试探争取，得到具体风险说明后可退出。')],[(603,650,'饭局引线'),(1026,1034,'父子关系'),(1246,1265,'拳术冲突'),(1438,1455,'调查组织'),(2470,2549,'利益和终局')],stats=(2,0,1,2,1,3))
h('sheng_adjutant','生副官（豪赌）',
'生副官是王常胜的旧部，也是后来寻宝者生念祖的父亲。家族长子沿用同一姓名，他同样叫生念祖，但两代人的经历与脾气不能互相覆盖。他曾凭家传相术注意到一个濒死少年，认为有大富之相，因而救下并带进军队。这个判断和少年后来致富相合，却不等于其能够准确预见任何个人、战役或自己家族的未来；救助和日后资助本身也是改变少年处境的实际行动。'
'王、李豪赌时，他负责洗牌，紧张到必须饮酒稳定双手。王输去部队后，他主动跟随离开，又说服王将盘缠交给少年经营。事业成功后，他长期陪伴王，自己并非商业长才。晚年身体衰弱，担心儿子无法处理祖传秘密，破例向有过命交情的朋友讲述，并托其帮助寻宝。他没有把父亲遇见帝王相青年的一切都交给儿子，叙事末尾将这种隐瞒解释为保护，但本人真实盘算不能全部确定。终局已经去世，卡片只保留生前可行动版本的明确部署，不因为子孙仍在而把家族记忆自动同步给他。',
'晚年向旧友托付家族秘密与寻宝心愿后去世；未亲见后续调查结果。','军中副官经验、洗牌操作、相术传统及识人；相术证据来自有限转述，不是全知预言。','重视旧主、救助者与朋友之间的长期信任，希望后人获得帮助而少受危害。',
[('失势旧主即将离开','自己的忠诚不只看权位','主动同行并另找生路。'),('看到困境中的潜在人才','既有判断也有实际帮助能力','提供食宿和工作，不能仅靠一句命相改变现实。'),('后人难以处理家族执念','自己将无法继续照顾','向可信旧友托付，并谨慎决定透露哪些信息。')],[(654,694,'副官和赌局'),(817,853,'随行与去世'),(858,881,'同名父子'),(1836,1898,'相术及救助'),(1941,1975,'托付与传承')],roles=['回忆主角'],dead=True,aliases=['生念祖（王常胜副官）'])
h('sheng_adjutant_father','生副官之父',
'生副官之父是生念祖寻宝者的祖父，家族数代居于京城，自称传有年羹尧一系相术与藏宝秘密。其子认为他相术远胜自己，这种评价是家族信念，不能直接换算为无限精确的预知。在京城大学堂附近遛鸟时，他看见一名瘦高青年，认定具有帝王之相，震惊失措，跌倒弄坏鸟笼，又向对方跪拜。青年并未施展精神法术，他的屈服来自自身的文化习惯、恐惧和判断。'
'他因担心隐瞒会招致家族灾祸，将秘密和地图呈给青年；对方阅读后归还，又与他谈论做皇帝的难处。他既希望青年得宝，自己可因献宝获利，又希望宝物终归子孙，矛盾愿望使其此后不断寻访却无结果。多年后向儿子讲述经过，没有明确交代青年身份，后人猜测这是冷静后意识到权势危险的保护。卡片将这一解释标作推测，保留老人有野心、敬畏权威、也可能修正决定的空间。眼光如电、五雷轰顶等描写是这场震惊的比喻，不给他或青年添加光束、雷击与无条件压制能力。',
'向儿子传下秘密与林中奇遇，未提供可核实的青年身份；已是后人追述中的故人。','传统相术、对外貌气度的观察、家族地图和历史记忆；真实性与预测范围有限。','寻找祖传宝物和家族出路，在敬畏权势与保护后人之间摇摆。',
[('遇到符合命相信念的人','长期观念压过冷静判断','可能失态献出秘密，须承受后果。'),('对方被视为不可违抗的权威','恐惧隐瞒会招祸','倾向讨好说明，不是受到必然精神控制。'),('有时间重新考虑','发现攀附也有危险','可以收住信息、避免后人冒险；具体原因保留推测。')],[(1949,1979,'家传与出遇'),(1981,2068,'惊惧行为'),(2098,2138,'献图和寻访'),(2507,2511,'保护后人的解释')],roles=['回忆主角'],dead=True,aliases=['生念祖的祖父（豪赌）'])
h('nian_gengyao','年羹尧（豪赌传说）',
'本卡是《豪赌》中经家族故事、白老大转述及卫斯理短篇改写呈现的年羹尧，不能作为真实历史人物的可靠传记。赌局里的玄衣青年以木盒异宝作抵，赢得三名波斯客的金刚钻；对方拔刀抢夺，他弹出钻石击中刀刃，使刀背反震伤人。随后叙述把青年指认为年羹尧，但其中已隔多重传闻与文学加工。可以在明确采用此传说版本时保留暗器技艺，不能把一次赌胜写成个人必然赢得任何战斗。'
'家族还称他靠相术判断四贝勒会继位，投身其门下，最终功高震主而遭满门抄杀。临危将小儿子和木盒托付忠仆，宣称宝物比皇位更可贵；为什么未借它自救，后人有无效、未使用、忠于君主等不同解释，故事没有拿到宝物检验。综合卡保留才干与臣属习惯的矛盾，不能用既定忠诚取消一切临场选择，也不从后人的推论倒灌他必然知道全部机制。终局已死亡，若以生前体态部署，其已知技能限于传说中展示的武艺及政治经历，必胜石不默认在手，更不赋予概率或概念操纵。',
'传说中遭处死，留下忠仆护送的幼子与宝物线索；细节均属小说内传闻。','传说中的钻石暗器、武艺及军政经历；必胜石的存在和作用未实证。','追求功业、维护家族，同时受既有臣属关系和忠诚观念束缚。',
[('赌局赢得财物后遭强抢','传说版本的武艺可用','以手边物反击，不能召唤无限金刚钻。'),('君主命令威胁自身','忠诚习惯与生存发生冲突','呈现痛苦抉择，不预设任何时代的人必然相同。'),('家族面临灭绝','仍有可信护送者','优先留下后人和线索，不把安排当作一定成功。')],[(36,85,'文学化赌局和暗器'),(397,416,'身份与托孤'),(421,457,'临危言语'),(1878,1883,'相术传闻'),(2394,2453,'未用宝物的假说')],stats=(3,0,1,3,2,4),roles=['传说主角'],dead=True,aliases=['年大将军（豪赌）'])
h('haodu_persian_gamblers','波斯赌客三人（豪赌传说）',
'这三名波斯赌客出现在卫斯理根据听闻写成的短篇里，属于《豪赌》的内嵌传说人物。他们带两百余颗金刚钻进入黄金赌场，愿意一次押下全部，见到陌生青年木盒中闪光后立即同意对赌。作者用其识宝反应营造木盒的重要性，但没有交代三人的姓名、来历、具体辨认方法或盒内确物，因此不能据此给每人增加鉴定所有宇宙奇物的能力。他们的共同作用是发动赌局后的暴力抢夺，原文没有足够个性资料拆成三张完整人物卡。'
'三人输掉赌局以后同时拔出半月形利刃袭击青年，反被钻石击刀，刀背反震到额头，倒地流血。原文明确不知死活，后来的转述也没有补全下落；终局部署可保留最后可战斗形态，但需标明其结果未知，不能写成已经复活。他们虽贪图异宝，也能在开赌前交流、判断和作出承诺，不必从出场起始终狂吼。能力按照普通持刀袭击、协同和识宝经验计，反震并不意味着他们具有和对手相同的力量。族别只作为故事身份，不概括现实群体的性格。',
'三人抢夺失败，额头受重击倒地，生死未明；后续无证实出场。','三人持刀近战和协同，有限识宝经验；此为小组卡，人数不随场景扩增。','获取珍宝和赌胜的满足，在损失与贪念刺激下可能撕毁约定。',
[('看到极有吸引力的宝物','误以为能够赢得或夺取','提高赌注并寻找接近机会。'),('已输却不肯接受','自认人数和武器占优','可能联手抢夺，也承担反击风险。'),('对方显露远强于预料的技艺','已有伤亡或行动受限','重新判断逃生，不能无限重复同样攻击。')],[(36,80,'赌局和袭击'),(81,104,'生死未明与传说层级'),(412,416,'后续无下落')],stats=(2,0,1,2,1,3),roles=['反派小组'],aliases=['三个波斯胡人（豪赌）'])
h('haodu_yongzheng','雍正皇帝（豪赌传说）',
'这张卡记录《豪赌》内部关于雍正的叙事形象，不用小说传闻替代真实史实。故事中的他从四贝勒成为皇帝，得到年羹尧效忠，又因忌惮功高而下令诛杀其一家。家族故事还称他派血滴子追捕幸存幼子与忠仆，使二人在长期隐匿中保全性命。血滴子的具体构造连卫斯理和白老大也未研究清楚，小说还专门区分传说和电影想象，因此这位皇帝不能被写成亲自熟练操使所有影视版本武器的超人。'
'他在本书没有当面与卫斯理交谈，其计划、恐惧与评价主要经后人讲述。卡片只把维护皇位、清除被认为可能威胁自己的臣属作为小说版本的行动逻辑，而不创造其知晓必胜石机制、从任意距离读取叛心的事实。年家传说中的小儿子仍然逃脱，也说明皇权命令不等于必然完成。终局是早已去世的历史背景人物，若跨世界部署，必须恢复为明确的小说生前版本，官署、军队和追捕组织须另行配置，不能把帝国面积作为个人攻击距离或将臣民生命算作无穷能量。',
'在家族后续传说发生前已去世；本书仅回述其对年家的处置。','小说版本的统治、任命及追捕组织经验；具体武艺和血滴子使用能力未证实。','保全皇位和控制臣属，对被视为威胁者采取强硬措施。',
[('臣属声望或功业被视为威胁','权位安全成为首要判断','可能先行压制，不能直接知道对方全部秘密。'),('追捕目标逃脱','仅能依赖情报和执行者','调动可用组织追查，命令仍可能失败。'),('别人奉上神奇宝物说法','来源和机制不明','以利益和控制考虑接受，不自动获得其宣称效果。')],[(353,394,'血滴子传说边界'),(421,452,'诛杀和追捕故事'),(1878,1883,'年家所述关系')],roles=['背景反派'],dead=True,aliases=['四贝勒（豪赌传说）'])
h('haodu_loyal_retainer','年家忠仆（豪赌）',
'这位未具名的忠仆是年羹尧家族传说中护送幼子的人。主人遇祸时，将未满月的孩子和装有异宝的木盒交给他，命其设法保存家族。传说说他经历十七次追杀，多次面对血滴子，最终在海外住了二十年；后来京城湖岛地图和木牌却使卫斯理等人认为，他可能从未离开京城，而把海外说法作为遮掩。两种叙述的冲突必须保留，不能同时写成可随意穿越海外与京城的能力。'
'他藏起物品，留下地图和四句口诀，再向长大的小主人说明身世，改年姓为生，随后病故。山洞、刻字与人群传说组成的隐匿设计，被后人解释为把秘密放进公众视线以降低怀疑，但具体细节有推理成分。卡片承认他有耐心、冒险精神及护送谋划，不由逃过追捕直接补出神行、隐身或击败全部追兵的武功。他把后人的存活放在当前名誉之前，能说谎、藏匿和延迟揭露，也可能因过度保密让后代困在误解里。终局已死，跨世界演绎须明确生前形态部署，宝物并不默认仍归他保管。',
'向长大的孩子交代家史与线索后病故；藏宝地点和逃亡路线的部分解释仍属后人推断。','护送、隐匿、设计线索与有限地图记录；无具体实战招式或超能证据。','保存受托孩子的性命和家族传承，愿承受长期隐姓埋名。',
[('幼主成为追杀目标','没有正面对抗的可靠优势','优先隐匿、转移与制造错误线索。'),('秘密将被公开','公开可能保护也可能暴露','比较实际人群和地形条件，不把反常策略当万能答案。'),('生命接近终点','传承信息仍只有自己掌握','尽可能说明线索，同时允许记录和传话出现误差。')],[(412,470,'托孤和后续'),(1457,1486,'木牌与藏匿推断')],roles=['回忆主角'],dead=True)
h('haodu_great_winner','大赢家（豪赌匿名人物）',
'本卡对应《豪赌》没有点明姓名的青年与后来被讨论的统治者，是小说叙述中的匿名政治人物，不替读者把暗示补成已核实的现实身份。在生副官之父的多层转述中，青年瘦高，穿半旧长衫，在树林抬头望天，看见鸟笼摔破后赞叹自由。他对老人跪拜起初惊讶，随后听完宝物故事、看图归还，以自负又带玩笑的口气谈论好皇帝。老人眼中的光辉和如雷言语只是畏惧描写，不是能量攻击或强制臣服技能。'
'卫斯理后来把这名青年和曾以政治、军事斗争获得巨大权力的人联系起来，认为其几经险境仍保有筹码，又把无数人的命运当成下注资源。铁大将军承认自己曾受其影响和伤害，却从未见过必胜石，也不相信宝物存在。故事收束仍提供多种互不相同的解释，所以他的成功不能反证概率操纵，更不能根据权势规模评为全能。卡片保留自由口号、个人抱负与后来控制他人的尖锐张力。若与其他篇章匿名领袖建立身份联系，须另有明确文本证据；单凭时代影射不足以自动合并所有老人家、元首或首长。',
'本篇只完成对其兴起与政治豪赌的回溯，未实证获得宝物，也未给出个人完整终局。','话语影响、政治与组织经验；军队和政权均为外部结构，宝物能力不计入。','争取改变世界的主导地位，并可能把自己的胜利置于他人的代价之上。',
[('别人主动奉其为命定领袖','既有抱负得到强化','可能接受恭维并索取信息，但并未读到对方思想。'),('重大目标遇挫','还有组织和资源可用','重新积累筹码，不能凭卡片保证每一局获胜。'),('他人要求自主或回报','与自身权力目标冲突','显现自由理念与控制欲的矛盾，作出具体而有代价的选择。')],[(1956,1962,'青年外貌'),(1981,1994,'鸟笼与自由'),(2098,2121,'还图和抱负'),(2558,2586,'政治关联'),(2588,2601,'无宝物证据'),(2630,2651,'开放解释')],roles=['背景反派'],aliases=['帝王之相青年（豪赌）'],stats=(1,0,1,2,1,3))
for c in C:
 if c['id'] in ['weisili_nian_gengyao','weisili_haodu_yongzheng','weisili_haodu_persian_gamblers','weisili_haodu_loyal_retainer','weisili_haodu_great_winner']:
  c['confidence']='low';c['rating_input']['rating_confidence']='low'
